package edu.lablink;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserJpaRepository users; public JwtAuthenticationFilter(JwtService jwt,UserJpaRepository users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{UserEntity u=users.findById(jwt.subject(h.substring(7))).orElse(null);if(u!=null&&"ACTIVE".equals(u.getStatus()))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole()))));}catch(Exception ignored){}c.doFilter(r,s);}}
